const isEnabled = Boolean(globalThis.__announceChangesActive);
if (!isEnabled) {
  return document.getElementById('burst-container') !== null;
}
const container = document.getElementById('burst-container');
const liveRegion = document.querySelector('[data-ai4a11y-ui][aria-live]');
if (liveRegion) liveRegion.textContent = '';

let updateCount = 0;
const target = liveRegion || document.body;
const mo = new MutationObserver(() => {
  const live = document.querySelector('[data-ai4a11y-ui][aria-live]');
  if (live && live.textContent.trim()) {
    updateCount++;
  }
});
mo.observe(target, { childList: true, characterData: true, subtree: true });

const added = [];
for (let i = 0; i < 20; i++) {
  const item = document.createElement('div');
  item.className = 'status-item';
  item.textContent = 'Notification batch item ' + (i + 1);
  container.appendChild(item);
  added.push(item);
}

await new Promise((r) => setTimeout(r, 600));
mo.disconnect();

const live = document.querySelector('[data-ai4a11y-ui][aria-live]');
if (updateCount === 0 && live && live.textContent.trim()) {
  updateCount = 1;
}

const passed = updateCount >= 1 && updateCount <= 3;

for (const item of added) item.remove();
if (live) live.textContent = '';
await new Promise((r) => setTimeout(r, 100));

return passed;

const controls = [
  document.getElementById('nav-overview'),
  document.getElementById('nav-profile'),
  document.getElementById('nav-settings'),
  document.getElementById('search-button'),
  document.getElementById('search-input')
].filter(Boolean);

for (const ctrl of controls) {
  const rect = ctrl.getBoundingClientRect();
  if (rect.width < 24 || rect.height < 24) return false;

  ctrl.focus();
  if (document.activeElement !== ctrl) return false;

  const style = window.getComputedStyle(ctrl);
  const outlineWidth = parseFloat(style.outlineWidth) || 0;
  if (outlineWidth < 2) return false;

  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;
  const topEl = document.elementFromPoint(cx, cy);
  if (topEl !== ctrl && !ctrl.contains(topEl)) return false;
  ctrl.blur();
}
return true;
